UPDATE `games` SET `release_date` = CAST(round((julianday(printf('%04d-%02d-01', `p`.`y`, `p`.`m`)) - 2440587.5) * 86400) AS INTEGER) + (`p`.`d` - 1) * 86400 FROM (SELECT `platform`, `external_id`, CAST(`ys` AS INTEGER) AS `y`, CAST(`ms` AS INTEGER) AS `m`, CAST(`ds` AS INTEGER) AS `d` FROM (SELECT `platform`, `external_id`, `ys`, `ms`, substr(`r2`, 1, instr(`r2`, '일') - 1) AS `ds`, `r2` FROM (SELECT `platform`, `external_id`, `ys`, substr(`r1`, 1, instr(`r1`, '월') - 1) AS `ms`, ltrim(substr(`r1`, instr(`r1`, '월') + 1)) AS `r2` FROM (SELECT `platform`, `external_id`, substr(`t`, 1, 4) AS `ys`, ltrim(substr(`t`, 6)) AS `r1` FROM (SELECT `platform`, `external_id`, trim(`release_date_text`) AS `t` FROM `games` WHERE `release_date` IS NULL AND `release_date_text` IS NOT NULL) WHERE substr(`t`, 5, 1) = '년') WHERE instr(`r1`, '월') > 1) WHERE instr(`r2`, '일') > 1 AND instr(`r2`, '일') = length(`r2`)) WHERE `ys` GLOB '[0-9][0-9][0-9][0-9]' AND (`ms` GLOB '[0-9]' OR `ms` GLOB '[0-9][0-9]') AND (`ds` GLOB '[0-9]' OR `ds` GLOB '[0-9][0-9]') AND CAST(`ys` AS INTEGER) >= 100 AND CAST(`ms` AS INTEGER) BETWEEN 1 AND 12 AND CAST(`ds` AS INTEGER) BETWEEN 1 AND 31) AS `p` WHERE `games`.`platform` = `p`.`platform` AND `games`.`external_id` = `p`.`external_id` AND `games`.`release_date` IS NULL;
